fn square_n(mut value: M31, count: usize) -> M31 {
    for _ in 0..count {
        value = value.mul(value);
    }
    value
}

fn inv(self) -> M31 {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::FInv);
        assert!(self.0 != 0, "inverse of zero");

        // Build x^(2^k - 1) at k = 2, 4, 8, 16, 24, 28, 29.
        // The final exponent is 4*(2^29 - 1) + 1 = 2^31 - 3 = P - 2.
        // This takes 38 M31 multiplications instead of the generic binary
        // exponentiation's 61 for this fixed exponent.
        let t2 = self.mul(self).mul(self);
        let t4 = square_n(t2, 2).mul(t2);
        let t8 = square_n(t4, 4).mul(t4);
        let t16 = square_n(t8, 8).mul(t8);
        let t24 = square_n(t16, 8).mul(t8);
        let t28 = square_n(t24, 4).mul(t4);
        let t29 = t28.mul(t28).mul(self);
        let t30 = t29.mul(t29);
        t30.mul(t30).mul(self)
    }

fn inv_with(self, inverse: fn(M31) -> M31) -> CM31 {
        let norm = self.a.mul(self.a).add(self.b.mul(self.b));
        let inv_norm = inverse(norm);
        CM31 {
            a: self.a.mul(inv_norm),
            b: self.b.neg().mul(inv_norm),
        }
    }

fn try_inv(self) -> Option<QM31> {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::KInv);
        if self.is_zero() {
            return None;
        }
        let norm = self.c0.square().sub(mul_by_r(self.c1.square()));
        let inverse_norm = norm.inv();
        Some(QM31 {
            c0: self.c0.mul(inverse_norm),
            c1: self.c1.neg().mul(inverse_norm),
        })
    }

fn inv(self) -> QM31 {
        self.try_inv().expect("cannot invert zero in QM31")
    }

fn secure_circle_point_from_parameter(
    parameter: QM31,
) -> Result<SecureCirclePoint, CirclePointError> {
    let square = parameter.square();
    let inverse_denominator = QM31::ONE
        .add(square)
        .try_inv()
        .ok_or(CirclePointError::SingularParameter)?;
    Ok(SecureCirclePoint {
        x: QM31::ONE.sub(square).mul(inverse_denominator),
        y: parameter.add(parameter).mul(inverse_denominator),
    })
}

fn secure_ood_circle_point_from_parameter(
    parameter: QM31,
) -> Result<SecureCirclePoint, CirclePointError> {
    // Check the singularity first so `t = ±i` has the precise algebraic error
    // even though those two roots also lie in CM31.
    let point = secure_circle_point_from_parameter(parameter)?;
    if parameter.c1 == CM31::ZERO {
        return Err(CirclePointError::ParameterInCm31Subfield);
    }
    Ok(point)
}

fn circle_fallback_point(sample: usize) -> SecureCirclePoint {
    let parameter = CIRCLE_FALLBACK_PARAMETERS[sample % 2];
    match secure_ood_circle_point_from_parameter(parameter) {
        Ok(point) => point,
        // Unreachable: `c1 = 1 ≠ 0` for both parameters.
        Err(_) => SecureCirclePoint {
            x: QM31::ONE,
            y: QM31::ZERO,
        },
    }
}

fn challenge_reference_circle_point(
        &mut self,
        sample: usize,
    ) -> Result<SecureCirclePoint, ChallengeSampleExhausted> {
        let parameter = self.challenge_qm31()?;
        Ok(secure_ood_circle_point_from_parameter(parameter)
            .unwrap_or_else(|_| circle_fallback_point(sample)))
    }

fn circle_sample(block: &[u8; 32], row: CircleRow) -> SecureCirclePoint {
    secure_ood_circle_point_from_parameter(qm31_sample(block)).unwrap_or_else(|_| {
        aspis_core::transcript::circle_fallback_point(match row {
            CircleRow::First => 0,
            CircleRow::Second => 1,
        })
    })
}
